"""Where uploaded files live.

Two backends behind one small interface: the local disk (development, tests, a single server
with a persistent volume) and any S3-compatible object store (AWS S3, Cloudflare R2, MinIO...).
Hosts with ephemeral disks need the second one, or uploads disappear on redeploy.
"""

import asyncio
import os
import re
import tempfile
from functools import lru_cache
from pathlib import Path
from typing import Any, Protocol

from fastapi.responses import FileResponse, RedirectResponse, Response

from app.core.config import Settings, get_settings

# Keys are generated by the server (a random id plus a fixed extension), but the backends
# still refuse anything that could climb out of their root.
_SAFE_KEY = re.compile(r"^[a-z0-9][a-z0-9/_.-]*$")


def _check_key(key: str) -> str:
    if not _SAFE_KEY.fullmatch(key) or ".." in key or "//" in key:
        raise ValueError(f"Unsafe storage key: {key!r}")
    return key


class Storage(Protocol):
    async def put(self, key: str, data: bytes, content_type: str) -> None: ...

    async def delete(self, key: str) -> None: ...

    async def exists(self, key: str) -> bool: ...

    def serve(self, key: str, content_type: str) -> Response:
        """A response that delivers the object, with range support (for seeking audio)."""
        ...


class LocalStorage:
    def __init__(self, root: str | Path) -> None:
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def _path(self, key: str) -> Path:
        path = (self.root / _check_key(key)).resolve()
        if self.root not in path.parents:
            raise ValueError(f"Unsafe storage key: {key!r}")
        return path

    async def put(self, key: str, data: bytes, content_type: str) -> None:
        path = self._path(key)

        def write() -> None:
            path.parent.mkdir(parents=True, exist_ok=True)
            # Write beside the target then rename, so a reader never sees half a file.
            fd, tmp = tempfile.mkstemp(dir=path.parent, suffix=".part")
            try:
                with os.fdopen(fd, "wb") as handle:
                    handle.write(data)
                os.replace(tmp, path)
            except BaseException:
                Path(tmp).unlink(missing_ok=True)
                raise

        await asyncio.to_thread(write)

    async def delete(self, key: str) -> None:
        await asyncio.to_thread(self._path(key).unlink, True)

    async def exists(self, key: str) -> bool:
        return await asyncio.to_thread(self._path(key).is_file)

    def serve(self, key: str, content_type: str) -> Response:
        # Starlette's FileResponse answers Range requests, which audio seeking relies on.
        return FileResponse(self._path(key), media_type=content_type)


class S3Storage:
    """S3-compatible object storage. Objects are never public: they are served by redirecting
    to a short-lived presigned URL, which also handles Range requests natively."""

    PRESIGN_SECONDS = 300

    def __init__(self, settings: Settings) -> None:
        import boto3
        from botocore.config import Config

        if not settings.s3_bucket:
            raise RuntimeError("STORAGE_BACKEND=s3 requires S3_BUCKET")
        self.bucket = settings.s3_bucket
        self._client: Any = boto3.client(
            "s3",
            endpoint_url=settings.s3_endpoint_url,
            region_name=settings.s3_region,
            aws_access_key_id=settings.s3_access_key_id,
            aws_secret_access_key=settings.s3_secret_access_key,
            config=Config(signature_version="s3v4", s3={"addressing_style": "path"}),
        )

    async def put(self, key: str, data: bytes, content_type: str) -> None:
        _check_key(key)
        await asyncio.to_thread(
            self._client.put_object,
            Bucket=self.bucket,
            Key=key,
            Body=data,
            ContentType=content_type,
        )

    async def delete(self, key: str) -> None:
        _check_key(key)
        await asyncio.to_thread(self._client.delete_object, Bucket=self.bucket, Key=key)

    async def exists(self, key: str) -> bool:
        from botocore.exceptions import ClientError

        _check_key(key)
        try:
            await asyncio.to_thread(self._client.head_object, Bucket=self.bucket, Key=key)
        except ClientError as error:
            if error.response.get("Error", {}).get("Code") in {"404", "NoSuchKey", "NotFound"}:
                return False
            raise
        return True

    def serve(self, key: str, content_type: str) -> Response:
        url = self._client.generate_presigned_url(
            "get_object",
            Params={
                "Bucket": self.bucket,
                "Key": _check_key(key),
                "ResponseContentType": content_type,
            },
            ExpiresIn=self.PRESIGN_SECONDS,
        )
        return RedirectResponse(url, status_code=307)


def build_storage(settings: Settings) -> Storage:
    if settings.storage_backend == "s3":
        return S3Storage(settings)
    return LocalStorage(settings.media_root)


@lru_cache
def get_storage() -> Storage:
    return build_storage(get_settings())
